// Episode 3 timeline: the locked edit plan (chapters, silent beats, narration groups) and the captions.
// Generated by scripts/timeline.py from production/scripts/ep03-gunpowder-plot/edit-plan.json + the caption SRT.
import tl from './timeline.json';

export const FPS = 30;
export const TOTAL = 21600;
export type Cue = {start: number; end: number; lines: string[]};
export const CUES: Cue[] = tl.captions as Cue[];
export const CHAPTERS = tl.chapters as {start: number; title: string; section: string}[];
export const BEATS = tl.beats as {section: string; kind: string; start: number; end: number}[];
export const GROUPS = tl.groups as {group: number; section: string; start: number; end: number}[];

const norm = (s: string) => s.toLowerCase().replace(/[’']/g, "'").replace(/[^a-z0-9' ]+/g, ' ').replace(/\s+/g, ' ').trim();
const CUE_TEXT = CUES.map((c) => norm(c.lines.join(' ')));

/** Time (s) of the caption cue that contains `phrase` (first match at or after `after` s). Throws if missing,
 *  so a script change that breaks an anchor fails the type-check/render instead of drifting silently. */
export function T(phrase: string, after = 0, edge: 'start' | 'end' = 'start'): number {
  const p = norm(phrase);
  const i = CUES.findIndex((c, k) => c.start >= after - 0.01 && CUE_TEXT[k].includes(p));
  if (i < 0) throw new Error('caption anchor not found: ' + phrase);
  return edge === 'start' ? CUES[i].start : CUES[i].end;
}
export const TE = (phrase: string, after = 0) => T(phrase, after, 'end');

/** Section window [start, end) in seconds. */
export function sectionWindow(id: string): [number, number] {
  const i = CHAPTERS.findIndex((c) => c.section === id);
  return [CHAPTERS[i].start, i + 1 < CHAPTERS.length ? CHAPTERS[i + 1].start : TOTAL / FPS];
}
/** The n-th silent beat of a section (0-based), as [start, end] seconds. */
export function beat(id: string, n: number): [number, number] {
  const b = BEATS.filter((x) => x.section === id)[n];
  return [b.start, b.end];
}
export const groupAt = (g: number) => GROUPS[g];
/** Is narration (any group) running at time t (s)? Used for the caption band. */
export const speaking = (t: number) => GROUPS.some((g) => t >= g.start - 0.15 && t <= g.end + 0.25);
export const cueAt = (t: number) => CUES.find((c) => t >= c.start && t < c.end + 0.12);
